def cad_mesh(key, color):
    """Return official-CAD facets and hard edges for a supported part."""
    encoded = _DATA.get(key)
    if encoded is None:
        return None

    raw = zlib.decompress(base64.b85decode(encoded))
    n_points, n_triangles = struct.unpack_from("<II", raw, 0)
    off = 8

    coords = struct.unpack_from(f"<{n_points * 3}h", raw, off)
    off += n_points * 3 * 2
    points = [
        (coords[i] / _Q, coords[i + 1] / _Q, coords[i + 2] / _Q)
        for i in range(0, len(coords), 3)
    ]

    indices = struct.unpack_from(f"<{n_triangles * 3}H", raw, off)
    off += n_triangles * 3 * 2
    # The oldest meshes carry one shading normal per triangle; everything
    # tools/iqdraw-cadmesh.py writes carries one per corner.  Read either,
    # averaging the corners - read as one per triangle, a per-corner mesh
    # shades every facet with some other facet's normal.
    smooth = struct.unpack_from(f"<{len(raw) - off}b", raw, off)
    corners = len(smooth) // (n_triangles * 3)

    facets = []
    geometric = []
    triangles = []
    for i in range(n_triangles):
        tri = indices[i * 3:i * 3 + 3]
        pts = [points[j] for j in tri]
        normal = polygon_normal(pts)
        s = smooth[i * 3 * corners:(i + 1) * 3 * corners]
        shade_normal = tuple(sum(s[c * 3 + k] for c in range(corners))
                             for k in range(3))
        length = sum(v * v for v in shade_normal) ** 0.5 or 1.0
        shade_normal = tuple(v / length for v in shade_normal)
        facets.append(Facet(pts, color, normal, shade_normal=shade_normal))
        geometric.append(normal)
        triangles.append(tri)

    # Recover only genuine CAD creases. Coordinate keys, rather than vertex
    # indices, join the duplicated vertices STEP tessellation creates at seams.
    edge_map = {}
    for fi, tri in enumerate(triangles):
        for a, b in ((tri[0], tri[1]), (tri[1], tri[2]), (tri[2], tri[0])):
            ka, kb = points[a], points[b]
            key = (ka, kb) if ka < kb else (kb, ka)
            edge_map.setdefault(key, []).append((fi, a, b))

    ec = outline_color(color)
    edges = []
    for entries in edge_map.values():
        if len(entries) != 2:
            continue
        (fa, a, b), (fb, _, _) = entries
        na, nb = geometric[fa], geometric[fb]
        if vdot(na, nb) < _CREASE:
            edges.append(Edge(points[a], points[b], ec, na, nb, 0.64))

    return facets + edges


def gear_mesh(teeth, color):
    """Return the official VEX CAD mesh for a supported spur gear."""
    return cad_mesh(teeth, color)
